, dim AS (
    SELECT d.ubigeo_reniec, d.departamento, f.r_vintage
    FROM fv f JOIN e_perm_aws.t_mst_ubigeos_rsk d ON f.ubigeo = d.ubigeo_sunat
)
, geo AS (
    SELECT key_value, max_by(cod_ubi_domicilio, fec_dato) AS ubi
    FROM e_perm_aws.t_mst_reniec_rsk
    WHERE cod_ubi_domicilio IS NOT NULL AND cod_ubi_domicilio <> ''
    GROUP BY key_value
)
, po AS (
    SELECT CAST(codmes AS INTEGER) AS codmes, id_value, flg_target_pp_12m AS y
    FROM disc_model_owner.pp_vc_ds_po_origpp
    WHERE flg_calib_rd = 1
      AND CAST(codmes AS INTEGER) BETWEEN 201901 AND 202504
      AND subproducto_ = '5.P FACIL'
      AND cod_instit_financiera = '00002'
)

, base AS (
    SELECT p.codmes, p.y,
           CASE WHEN d.r_vintage >= 4 THEN 'R45' WHEN d.r_vintage = 3 THEN 'R3'
                WHEN d.r_vintage >= 1 THEN 'R12' ELSE 'R0' END AS g
    FROM po p JOIN geo g2 ON p.id_value = g2.key_value JOIN dim d ON g2.ubi = d.ubigeo_reniec
)
SELECT codmes,
       sum(CASE WHEN g='R0' THEN 1 ELSE 0 END) AS n_R0,
       round(100.0*sum(CASE WHEN g='R0' THEN y ELSE 0 END)
             / nullif(sum(CASE WHEN g='R0' THEN 1 ELSE 0 END),0), 4) AS rd_R0,
       sum(CASE WHEN g='R12' THEN 1 ELSE 0 END) AS n_R12,
       round(100.0*sum(CASE WHEN g='R12' THEN y ELSE 0 END)
             / nullif(sum(CASE WHEN g='R12' THEN 1 ELSE 0 END),0), 4) AS rd_R12,
       sum(CASE WHEN g='R3' THEN 1 ELSE 0 END) AS n_R3,
       round(100.0*sum(CASE WHEN g='R3' THEN y ELSE 0 END)
             / nullif(sum(CASE WHEN g='R3' THEN 1 ELSE 0 END),0), 4) AS rd_R3,
       sum(CASE WHEN g='R45' THEN 1 ELSE 0 END) AS n_R45,
       round(100.0*sum(CASE WHEN g='R45' THEN y ELSE 0 END)
             / nullif(sum(CASE WHEN g='R45' THEN 1 ELSE 0 END),0), 4) AS rd_R45
FROM base GROUP BY codmes ORDER BY codmes
